define({"topics":[{"title":"Logging on as root","shortdesc":"<p class=\"shortdesc\">Use this procedure to log on as root.<\/p>","href":"t_LoggingInAsRoot_2.html","attributes":{"data-id":"id_2004204"},"menu":{"hasChildren":false},"tocID":"id_2004204-d46e61207","topics":[]},{"title":"Configuring user access for RSD","shortdesc":"<p class=\"shortdesc\">The option <span class=\"ph uicontrol\">Only allow authorized users to install updates<\/span> is the default preference when setting up preferences for receiving software updates. This option lets only root users and also EA3 authorized users (role-based authorization) to install a new service pack. Use this procedure to establish authorization for individual EA2 users.<\/p>","href":"t_ConfiguringUserAccessForRSD_2.html","attributes":{"data-id":"id_2004041"},"menu":{"hasChildren":false},"tocID":"id_2004041-d46e61312","topics":[]}]});